package ai.interviewiq.api.exception;
import ai.interviewiq.api.service.AiProviderException; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { record ErrorBody(Error error){} record Error(String code,String message){} private ResponseEntity<ErrorBody> response(HttpStatus s,String c,String m){return ResponseEntity.status(s).body(new ErrorBody(new Error(c,m)));} @ExceptionHandler(ApiException.class) ResponseEntity<ErrorBody> api(ApiException e){return response(e.status(),e.code(),e.getMessage());} @ExceptionHandler(AiProviderException.class) ResponseEntity<ErrorBody> ai(AiProviderException e){return response(HttpStatus.SERVICE_UNAVAILABLE,"AI_PROVIDER_UNAVAILABLE","AI feedback is temporarily unavailable. Please try again.");} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorBody> validation(){return response(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","One or more fields are invalid.");} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ErrorBody> denied(){return response(HttpStatus.FORBIDDEN,"FORBIDDEN","Access is denied.");} @ExceptionHandler(Exception.class) ResponseEntity<ErrorBody> unexpected(Exception e){return response(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","An unexpected error occurred.");} }
